tokens:
/* Glass cards: bounded surfaces over photography/video, never whole-page opacity. */
--glass-card-teal-surface: linear-gradient(135deg,rgba(15,60,58,.78),rgba(8,35,40,.66) 55%,rgba(27,91,78,.72));
--glass-card-teal-solid: #153d3b;
--glass-card-teal-border: #8debd25c;
--glass-card-slate-surface: linear-gradient(135deg,rgba(42,54,82,.78),rgba(16,36,52,.68));
--glass-card-slate-solid: #26364b;
--glass-card-slate-border: #b5bcff40;
--color-on-glass: var(--color-white);
--glass-card-blur: 8px;
--glass-card-shadow: inset 0 0 32px #94ffe508, 0 25px 55px #0004;
--glass-card-focus-ring: 2px solid var(--color-on-glass);

components:
/* Glass variant: content remains opaque; only the surface is translucent. */
.wf-card--glass{
 --glass-surface:var(--glass-card-teal-surface);--glass-solid:var(--glass-card-teal-solid);--glass-border:var(--glass-card-teal-border);
 box-sizing:border-box;display:flex;flex-direction:column;align-items:stretch;gap:var(--space-3);min-width:0;
 padding:var(--space-6);border:1px solid var(--glass-border);border-radius:var(--radius-card);
 background:var(--glass-solid);color:var(--color-on-glass);box-shadow:var(--glass-card-shadow);text-align:left;
}
.wf-card--glass-slate{--glass-surface:var(--glass-card-slate-surface);--glass-solid:var(--glass-card-slate-solid);--glass-border:var(--glass-card-slate-border)}
@supports ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){
 .wf-card--glass{background:var(--glass-surface);backdrop-filter:blur(var(--glass-card-blur));-webkit-backdrop-filter:blur(var(--glass-card-blur))}
}
.wf-card--glass .wf-card__title{margin:0;font-family:var(--font-display);font-size:var(--font-size-heading);font-weight:var(--font-weight-bold);line-height:var(--line-height-tight);letter-spacing:normal;color:var(--color-on-glass);overflow-wrap:anywhere}
.wf-card--glass .wf-card__title:lang(en){font-family:var(--font-display-en)}
.wf-card--glass .wf-card__action{
 align-self:flex-start;display:inline-flex;align-items:center;gap:var(--space-2);min-height:var(--control-height-touch);
 padding:0 var(--space-2);margin-left:calc(-1 * var(--space-2));border:1px solid transparent;border-radius:var(--radius-control);
 background:transparent;color:var(--color-on-glass);font-family:var(--font-body);font-size:var(--font-size-sm);font-weight:var(--font-weight-semibold);line-height:var(--line-height-tight);
 text-decoration:underline;text-underline-offset:var(--space-1);cursor:pointer;
 transition:background-color var(--duration-fast) var(--ease-standard),color var(--duration-fast) var(--ease-standard),border-color var(--duration-fast) var(--ease-standard);
}
.wf-card--glass .wf-card__action:not(:disabled):hover{background:var(--color-surface-hover);color:var(--color-action-hover)}
.wf-card--glass .wf-card__action:focus-visible{outline:var(--glass-card-focus-ring);outline-offset:var(--focus-offset);background:var(--color-surface);color:var(--color-action)}
.wf-card--glass .wf-card__action:not(:disabled):active{background:var(--color-surface-subtle);border-color:var(--color-action)}
.wf-card--glass .wf-card__action:disabled{opacity:1;cursor:default;text-decoration:none}
.wf-card--glass .wf-card__status{display:flex;align-items:center;min-height:var(--control-height-touch);font-family:var(--font-body);font-size:var(--font-size-sm);font-weight:var(--font-weight-semibold);line-height:var(--line-height-tight);color:var(--color-on-glass)}
@media(prefers-reduced-transparency:reduce){.wf-card--glass{background:var(--glass-solid);backdrop-filter:none;-webkit-backdrop-filter:none}}
@media(forced-colors:active){
 .wf-card--glass{background:Canvas;color:CanvasText;border-color:CanvasText;box-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none}
 .wf-card--glass .wf-card__title,.wf-card--glass .wf-card__status{color:CanvasText}
 .wf-card--glass .wf-card__action{color:LinkText}
 .wf-card--glass .wf-card__action:focus-visible{outline-color:Highlight}
}
